<?php get_header(); ?><main id="main-content" class="container page-wrap"><header class="page-heading"><span class="eyebrow"><?php esc_html_e('SEARCH JAVTEEN','javteen'); ?></span><h1><?php printf(esc_html__('Results for “%s”','javteen'),esc_html(get_search_query())); ?></h1><?php get_search_form(); ?></header><?php if(have_posts()): ?><div class="video-grid"><?php while(have_posts()):the_post();if('video'===get_post_type()){get_template_part('template-parts/video-card');}else{?><article class="post-row"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php }endwhile; ?></div><?php the_posts_pagination(); else: ?><div class="empty-state"><h2><?php esc_html_e('No matching videos found','javteen'); ?></h2><p><?php esc_html_e('Try a different title or keyword.','javteen'); ?></p></div><?php endif; ?></main><?php get_footer(); ?>